package com.primehr.evidence.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;import java.util.Locale;
@Entity@Table(name="evidence_assessment_case",uniqueConstraints=@UniqueConstraint(name="uk_evidence_case_code",columnNames={"agency_id","cycle_id","normalized_code"}))
public class EvidenceAssessmentCase extends RspAuditedEntity{
 public enum Status{DRAFT,SUBMITTED,RETURNED,RESUBMITTED,FINALIZED,WITHDRAWN}
 @Column(name="content_revision",nullable=false)private int contentRevision;
 @Column(name="cycle_id",nullable=false,length=36)private String cycleId;@Column(name="framework_version_id",nullable=false,length=36)private String frameworkVersionId;@Column(nullable=false,length=80)private String code;@Column(name="normalized_code",nullable=false,length=80)private String normalizedCode;@Column(nullable=false,length=250)private String title;@Column(name="organization_type",nullable=false,length=30)private String organizationType;@Column(name="organization_id")private Long organizationId;@Column(name="organization_name",nullable=false,length=250)private String organizationName;@Column(name="organization_fingerprint",nullable=false,length=64)private String organizationFingerprint;
 @Column(name="owner_employee_id",nullable=false)private Long ownerEmployeeId;@Column(name="owner_employee_no",nullable=false,length=100)private String ownerEmployeeNo;@Column(name="owner_name",nullable=false,length=250)private String ownerName;@Column(name="owner_appointment_id",nullable=false)private Long ownerAppointmentId;@Column(name="owner_fingerprint",nullable=false,length=64)private String ownerFingerprint;
 @Column(name="validator_employee_id",nullable=false)private Long validatorEmployeeId;@Column(name="validator_employee_no",nullable=false,length=100)private String validatorEmployeeNo;@Column(name="validator_name",nullable=false,length=250)private String validatorName;@Column(name="validator_appointment_id",nullable=false)private Long validatorAppointmentId;@Column(name="validator_fingerprint",nullable=false,length=64)private String validatorFingerprint;@Column(name="validator_recused",nullable=false)private boolean validatorRecused;@Column(name="recusal_reason",length=2000)private String recusalReason;
 @Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="submission_revision",nullable=false)private int submissionRevision;@Column(name="submitted_by",length=100)private String submittedBy;@Column(name="submitted_at")private Instant submittedAt;@Column(name="returned_by",length=100)private String returnedBy;@Column(name="returned_at")private Instant returnedAt;@Column(name="return_reason",length=3000)private String returnReason;@Column(name="finalized_by",length=100)private String finalizedBy;@Column(name="finalized_at")private Instant finalizedAt;@Column(name="finalization_reason",length=3000)private String finalizationReason;@Column(name="withdrawn_by",length=100)private String withdrawnBy;@Column(name="withdrawn_at")private Instant withdrawnAt;@Column(name="withdrawal_reason",length=3000)private String withdrawalReason;
 protected EvidenceAssessmentCase(){}public EvidenceAssessmentCase(String a,String cycle,String framework,String code,String title,String orgType,Long orgId,String orgName,String orgFingerprint,Person owner,Person validator){super(a);cycleId=requiredText(cycle,"cycleId");frameworkVersionId=requiredText(framework,"frameworkVersionId");this.code=requiredText(code,"code");normalizedCode=this.code.toUpperCase(Locale.ROOT);this.title=requiredText(title,"title");organizationType=requiredText(orgType,"organizationType").toUpperCase(Locale.ROOT);organizationId=orgId;organizationName=requiredText(orgName,"organizationName");organizationFingerprint=requiredText(orgFingerprint,"organizationFingerprint");assignOwner(owner);assignValidator(validator);if(owner.employeeNo().equalsIgnoreCase(validator.employeeNo()))throw new IllegalArgumentException("Evidence owner and validator must be different employees");status=Status.DRAFT;}
 public record Person(Long employeeId,String employeeNo,String name,Long appointmentId,String fingerprint){}
 private void assignOwner(Person p){if(p==null||p.employeeId()==null||p.appointmentId()==null)throw new IllegalArgumentException("Complete owner appointment snapshot is required");ownerEmployeeId=p.employeeId();ownerEmployeeNo=requiredText(p.employeeNo(),"ownerEmployeeNo");ownerName=requiredText(p.name(),"ownerName");ownerAppointmentId=p.appointmentId();ownerFingerprint=requiredText(p.fingerprint(),"ownerFingerprint");}
 private void assignValidator(Person p){if(p==null||p.employeeId()==null||p.appointmentId()==null)throw new IllegalArgumentException("Complete validator appointment snapshot is required");validatorEmployeeId=p.employeeId();validatorEmployeeNo=requiredText(p.employeeNo(),"validatorEmployeeNo");validatorName=requiredText(p.name(),"validatorName");validatorAppointmentId=p.appointmentId();validatorFingerprint=requiredText(p.fingerprint(),"validatorFingerprint");validatorRecused=false;recusalReason=null;}
 public void update(String title,String orgType,Long orgId,String orgName,String orgFingerprint){editable();this.title=requiredText(title,"title");organizationType=requiredText(orgType,"organizationType").toUpperCase(Locale.ROOT);organizationId=orgId;organizationName=requiredText(orgName,"organizationName");organizationFingerprint=requiredText(orgFingerprint,"organizationFingerprint");contentRevision++;}
 public void contentChanged(){editable();contentRevision++;}public void reviewChanged(){if(status!=Status.SUBMITTED&&status!=Status.RESUBMITTED)throw new IllegalStateException("Only a submitted case may receive review content");contentRevision++;}
 public void submit(String actor,Instant at){if(status!=Status.DRAFT&&status!=Status.RETURNED)throw new IllegalStateException("Only a draft or returned case may be submitted");if(!ownerEmployeeNo.equalsIgnoreCase(actor))throw new IllegalArgumentException("Only the assigned evidence owner may submit the case");submissionRevision++;status=submissionRevision==1?Status.SUBMITTED:Status.RESUBMITTED;submittedBy=actor;submittedAt=at;}
 public void returnForRework(String actor,String reason,Instant at){reviewable(actor);status=Status.RETURNED;returnedBy=actor;returnedAt=at;returnReason=requiredText(reason,"reason");}
 public void finalizeCase(String actor,String reason,Instant at){reviewable(actor);status=Status.FINALIZED;finalizedBy=actor;finalizedAt=at;finalizationReason=requiredText(reason,"reason");}
 public void withdraw(String actor,String reason,Instant at){if(status==Status.FINALIZED||status==Status.WITHDRAWN)throw new IllegalStateException("The case cannot be withdrawn");if(!ownerEmployeeNo.equalsIgnoreCase(actor))throw new IllegalArgumentException("Only the assigned evidence owner may withdraw the case");status=Status.WITHDRAWN;withdrawnBy=actor;withdrawnAt=at;withdrawalReason=requiredText(reason,"reason");}
 public void recuse(String actor,String reason){if(!validatorEmployeeNo.equalsIgnoreCase(actor))throw new IllegalArgumentException("Only the assigned validator may recuse");if(status==Status.FINALIZED||status==Status.WITHDRAWN)throw new IllegalStateException("The validator can no longer recuse");validatorRecused=true;recusalReason=requiredText(reason,"reason");}
 public void reassignValidator(Person p){if(status==Status.FINALIZED||status==Status.WITHDRAWN)throw new IllegalStateException("The validator can no longer be reassigned");if(ownerEmployeeNo.equalsIgnoreCase(p.employeeNo()))throw new IllegalArgumentException("Evidence owner and validator must be different employees");assignValidator(p);}
 public void editable(){if(status!=Status.DRAFT&&status!=Status.RETURNED)throw new IllegalStateException("Only a draft or returned case may be changed");}public void reviewable(String actor){if(status!=Status.SUBMITTED&&status!=Status.RESUBMITTED)throw new IllegalStateException("Only a submitted case may be reviewed");if(validatorRecused)throw new IllegalStateException("A recused validator cannot review the case");if(!validatorEmployeeNo.equalsIgnoreCase(actor))throw new IllegalArgumentException("Only the assigned validator may review the case");if(ownerEmployeeNo.equalsIgnoreCase(actor))throw new IllegalArgumentException("The evidence owner cannot validate the same case");}
 public String getOrganizationFingerprint(){return organizationFingerprint;}public int getContentRevision(){return contentRevision;}
 public String getCycleId(){return cycleId;}public String getFrameworkVersionId(){return frameworkVersionId;}public String getCode(){return code;}public String getTitle(){return title;}public String getOrganizationType(){return organizationType;}public Long getOrganizationId(){return organizationId;}public String getOrganizationName(){return organizationName;}public Long getOwnerEmployeeId(){return ownerEmployeeId;}public String getOwnerEmployeeNo(){return ownerEmployeeNo;}public String getOwnerName(){return ownerName;}public Long getOwnerAppointmentId(){return ownerAppointmentId;}public String getOwnerFingerprint(){return ownerFingerprint;}public Long getValidatorEmployeeId(){return validatorEmployeeId;}public String getValidatorEmployeeNo(){return validatorEmployeeNo;}public String getValidatorName(){return validatorName;}public Long getValidatorAppointmentId(){return validatorAppointmentId;}public String getValidatorFingerprint(){return validatorFingerprint;}public boolean isValidatorRecused(){return validatorRecused;}public String getRecusalReason(){return recusalReason;}public Status getStatus(){return status;}public int getSubmissionRevision(){return submissionRevision;}public String getSubmittedBy(){return submittedBy;}public Instant getSubmittedAt(){return submittedAt;}public String getReturnedBy(){return returnedBy;}public Instant getReturnedAt(){return returnedAt;}public String getReturnReason(){return returnReason;}public String getFinalizedBy(){return finalizedBy;}public Instant getFinalizedAt(){return finalizedAt;}public String getFinalizationReason(){return finalizationReason;}public String getWithdrawnBy(){return withdrawnBy;}public Instant getWithdrawnAt(){return withdrawnAt;}public String getWithdrawalReason(){return withdrawalReason;}
}
